mapper.select:
SELECT COUNT(DISTINCT visitor_id)
FROM analytics_visits
WHERE created_at >= #{since}

SELECT COUNT(*)
FROM analytics_visits
WHERE created_at >= #{since}

SELECT COUNT(DISTINCT session_id)
FROM analytics_visits
WHERE created_at >= #{since}

SELECT path, COUNT(*) AS cnt
FROM analytics_visits
WHERE created_at >= #{since}

GROUP BY path
ORDER BY cnt DESC
LIMIT #{limit}

SELECT path, COUNT(*) AS cnt
FROM (
    SELECT session_id, MIN(path) AS path
    FROM analytics_visits
    WHERE created_at >= #{since}

    GROUP BY session_id
) AS firsts
GROUP BY path
ORDER BY cnt DESC
LIMIT #{limit}

SELECT session_id AS sessionId, visitor_id AS visitorId, path, referrer, created_at AS createdAt FROM analytics_visits WHERE session_id IN
#{sid}
ORDER BY created_at ASC
